var scene = UnityEngine.SceneManagement.SceneManager.GetSceneByName("City");
var roots = scene.GetRootGameObjects();
int count = 0;
foreach (var r in roots) {
    foreach (var f in r.GetComponentsInChildren<TMPro.TMP_InputField>(true)) {
        string p = f.transform.name;
        var t = f.transform; while (t.parent != null) { t = t.parent; p = t.name + "/" + p; }
        Debug.Log("InputField: " + p + " iid=" + f.GetInstanceID() + " multiline=" + f.lineType);
        count++;
        if (count >= 8) return;
    }
}
Debug.Log("Total: " + count);
